21fb4b16473dddf250678aa669b61fd6:
query StoragePanelQuery {
  photographer {
    storage {
      totalBytes
      hotBytes
      archivedBytes
      archiveAvailable
      albums {
        albumId
        name
        photoCount
        bytes
        originalBytes
        archivedBytes
        transition
      }
    }
    id
  }
}

